class Solution {
    public boolean checkValidString(String s){
        int low=0,high=0;
        for(char c:s.toCharArray()){
            if(c=='('){
                low++;
                high++;
            }else if(c==')'){
                low--;
                high--;
            }else{
                low--;
                high++;
            }
            if(high<0)return false;
            low=Math.max(low,0);
        }
        return low==0;
    }
}

code.kotlin:
class Solution {
    fun checkValidString(s:String):Boolean{
        var low=0;
        var high=0;
        for(c in s){
            when(c){
                '('->{
                    low++;
                    high++
                };
                ')'->{
                    low--;
                    high--
                };
                else->{
                    low--;
                    high++
                }
            };
            if(high<0)return false;
            low=maxOf(low,0)
        };
        return low==0
    }
}

code.cpp:
class Solution {
    public: bool checkValidString(string s){
        int low=0,high=0;
        for(char c:s){
            if(c=='('){
                ++low;
                ++high;
            }else if(c==')'){
                --low;
                --high;
            }else{
                --low;
                ++high;
            }
            if(high<0)return false;
            low=max(low,0);
        }
        return low==0;
    }
};
